 G.gorselbaslik.q=R.map((r,n)=>['Görsele en uygun başlığı seç.',r.visual,r.title,opts(r.title,titles,n)]);
 G.gorselmetin.q=R.map((r,n)=>['Görsele uygun kısa metni seç.',r.visual,textOf(r),opts(textOf(r),texts,n)]);

